<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';
require __DIR__.'/../app/commerce.php';
require __DIR__.'/../app/editorial.php';
$path = parse_url($_SERVER['REQUEST_URI'], PHP_URL_PATH) ?: '/';
$me = user($db);
$settings = $db->query('SELECT setting_key,setting_value FROM settings')->fetchAll(PDO::FETCH_KEY_PAIR);
function log_action(PDO $db, int $id, string $action): void { $q=$db->prepare('INSERT INTO activity_logs(actor_id,action) VALUES(?,?)'); $q->execute([$id,$action]); }
if ($_SERVER['REQUEST_METHOD']==='POST') {
    verify_csrf();
    if (business_post($db, $path, $me, $settings) || editorial_post($db, $path, $me)) exit;
    if ($path==='/logout') { $_SESSION=[]; session_destroy(); redirect('/'); }
    if ($path==='/login' || $path==='/register') {
        // A shared per-IP limit also applies to registration; old records can be pruned periodically.
        $ip=hash('sha256', $_SERVER['REMOTE_ADDR'] ?? 'unknown');
        $q=$db->prepare('SELECT COUNT(*) FROM login_attempts WHERE ip_hash=? AND attempted_at > (CURRENT_TIMESTAMP - INTERVAL 15 MINUTE)'); $q->execute([$ip]);
        if ((int)$q->fetchColumn() >= 10) { http_response_code(429); exit('Too many attempts. Please try again later.'); }
        $q=$db->prepare('INSERT INTO login_attempts(ip_hash) VALUES(?)'); $q->execute([$ip]);
        $email=strtolower(trim((string)($_POST['email'] ?? ''))); $password=(string)($_POST['password'] ?? '');
        if ($path==='/register') {
            $name=trim((string)($_POST['name'] ?? ''));
            if ($name==='' || mb_strlen($name)>100 || !filter_var($email,FILTER_VALIDATE_EMAIL) || strlen($email)>190 || strlen($password)<12 || strlen($password)>72) { flash('Please provide a valid name and email and a password of at least 12 characters.'); redirect('/register'); }
            try { $q=$db->prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)'); $q->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]); }
            catch (PDOException $ex) { if ($ex->getCode() !== '23000') throw $ex; flash('Unable to create this account. Try signing in instead.'); redirect('/register'); }
            session_regenerate_id(true); $_SESSION['uid']=(int)$db->lastInsertId(); redirect('/dashboard');
        }
        if (strlen($password)>72 || strlen($email)>190) { flash('Invalid email or password.'); redirect('/login'); }
        $q=$db->prepare('SELECT id,password_hash,active FROM users WHERE email=?'); $q->execute([$email]); $account=$q->fetch(PDO::FETCH_ASSOC);
        if (!$account || !$account['active'] || !password_verify($password,$account['password_hash'])) { flash('Invalid email or password.'); redirect('/login'); }
        session_regenerate_id(true); $_SESSION['uid']=(int)$account['id']; redirect('/dashboard');
    }
    if ($path==='/admin/settings') {
        require_admin($me);
        $title=trim((string)($_POST['hero_title'] ?? '')); $text=trim((string)($_POST['hero_text'] ?? '')); $email=trim((string)($_POST['contact_email'] ?? '')); $instructions=trim((string)($_POST['payment_instructions'] ?? ''));
        if ($title==='' || mb_strlen($title)>150 || mb_strlen($text)>500 || mb_strlen($instructions)>1000 || ($email!=='' && (!filter_var($email,FILTER_VALIDATE_EMAIL) || strlen($email)>190))) { flash('Check the title, description and contact email.'); redirect('/admin/settings'); }
        $db->beginTransaction();
        $q=$db->prepare('UPDATE settings SET setting_value=? WHERE setting_key=?'); foreach (['hero_title'=>$title,'hero_text'=>$text,'contact_email'=>$email,'payment_instructions'=>$instructions] as $k=>$v) $q->execute([$v,$k]);
        log_action($db,(int)$me['id'],'Updated homepage settings'); $db->commit(); flash('Settings saved.'); redirect('/admin/settings');
    }
    if ($path==='/admin/services') {
        require_admin($me); $action=(string)($_POST['action'] ?? 'save'); $id=filter_var($_POST['id'] ?? 0,FILTER_VALIDATE_INT) ?: 0;
        if ($action==='delete' && $id>0) { $db->beginTransaction(); $q=$db->prepare('UPDATE services SET active=0 WHERE id=?'); $q->execute([$id]); log_action($db,(int)$me['id'],'Archived service #'.$id); $db->commit(); flash('Service archived.'); redirect('/admin/services'); }
        if ($action!=='save') { http_response_code(400); exit('Invalid action.'); }
        $title=trim((string)($_POST['title'] ?? '')); $category=trim((string)($_POST['category'] ?? '')); $description=trim((string)($_POST['description'] ?? '')); $price=trim((string)($_POST['price_note'] ?? '')); $sort=filter_var($_POST['sort_order'] ?? '0',FILTER_VALIDATE_INT);
        if ($title==='' || mb_strlen($title)>150 || $category==='' || mb_strlen($category)>80 || mb_strlen($description)>5000 || mb_strlen($price)>150 || $sort===false || abs($sort)>1000000) { flash('Please check the service fields.'); redirect('/admin/services'); }
        $rate=filter_var($_POST['rate_poisha_per_1000'] ?? '',FILTER_VALIDATE_INT); $min=filter_var($_POST['min_quantity'] ?? '',FILTER_VALIDATE_INT); $max=filter_var($_POST['max_quantity'] ?? '',FILTER_VALIDATE_INT); if ($rate===false || $rate<0 || $rate>100000000 || !$min || !$max || $min<1 || $max<$min || $max>1000000) { flash('Check rate and quantity limits.'); redirect('/admin/services'); }
        $active=isset($_POST['active']) ? 1 : 0; $db->beginTransaction();
        if ($id>0) { $q=$db->prepare('UPDATE services SET title=?,category=?,description=?,price_note=?,sort_order=?,active=?,rate_poisha_per_1000=?,min_quantity=?,max_quantity=? WHERE id=?'); $q->execute([$title,$category,$description,$price,$sort,$active,$rate,$min,$max,$id]); }
        else { $q=$db->prepare('INSERT INTO services(title,category,description,price_note,sort_order,active,rate_poisha_per_1000,min_quantity,max_quantity) VALUES(?,?,?,?,?,?,?,?,?)'); $q->execute([$title,$category,$description,$price,$sort,$active,$rate,$min,$max]); $id=(int)$db->lastInsertId(); }
        log_action($db,(int)$me['id'],'Saved service #'.$id); $db->commit(); flash('Service saved.'); redirect('/admin/services');
    }
    http_response_code(404); exit('Not found');
}
$allowed=['/','/services','/login','/register','/dashboard','/admin','/admin/services','/admin/settings','/orders/new','/orders','/wallet','/support','/admin/orders','/admin/deposits','/admin/support','/blog','/article','/admin/blog','/admin/users'];
if (!in_array($path,$allowed,true)) { http_response_code(404); $path='/404'; }
if (str_starts_with($path,'/admin')) require_admin($me);
if (in_array($path,['/dashboard','/orders/new','/orders','/wallet','/support'],true)) require_user($me);
$services=[]; if ($path==='/services' || $path==='/admin/services') $services=$db->query('SELECT * FROM services '.($path==='/services'?'WHERE active=1 ':'').'ORDER BY sort_order,id LIMIT 200')->fetchAll(PDO::FETCH_ASSOC);
$edit=null; if ($path==='/admin/services' && isset($_GET['edit'])) { $q=$db->prepare('SELECT * FROM services WHERE id=?'); $q->execute([(int)$_GET['edit']]); $edit=$q->fetch(PDO::FETCH_ASSOC) ?: null; }
$notice=take_flash(); $isAdmin=str_starts_with($path,'/admin');
