<?php if ($isAdmin): ?><div class="admin-shell"><aside class="sidebar"><a class="brand" href="/">M<span>✳</span> MEXA <small>MOTION</small></a><p class="sidebar-label">WORKSPACE</p><a href="/admin">Overview</a><a href="/admin/services">Services</a><a href="/admin/users">Users</a><a href="/admin/blog">Blog</a><a href="/admin/orders">Orders</a><a href="/admin/deposits">Payments</a><a href="/admin/support">Support</a><a href="/admin/settings">Site settings</a><a href="/dashboard">My account</a><div class="sidebar-foot">MEXA MOTION<br><small>Administration</small></div></aside><div class="admin-main"><header class="admin-header"><span>Administration</span><a href="/">View website ↗</a></header><main class="admin-content"><?php else: ?><header class="header"><div class="wrap nav"><a class="brand" href="/">M<span>✳</span> MEXA <small>MOTION</small></a><nav aria-label="Main navigation"><a href="/services">Services</a><a href="/blog">Journal</a><?php if ($me): ?><a href="/dashboard">Dashboard</a><a href="/orders">Orders</a><a href="/wallet">Wallet</a><a href="/support">Support</a><?php if ($me['role']==='admin'): ?><a href="/admin">Admin</a><?php endif ?><form method="post" action="/logout"><?=csrf_field()?><button class="nav-link">Log out</button></form><?php else: ?><a href="/login">Log in</a><a class="btn btn-small" href="/register">Get started <span>↗</span></a><?php endif ?></nav></div></header><main><?php endif ?>
