<?php elseif ($path==='/services'): ?><section class="page wrap"><div class="eyebrow">THE CATALOGUE</div><h1>Find your next move.</h1><p class="lead">Explore the services currently available from MEXA MOTION.</p><div class="service-grid"><?php foreach($services as $s): ?><article class="service-card"><div class="eyebrow"><?=e($s['category'])?></div><h2><?=e($s['title'])?></h2><p><?=nl2br(e($s['description']))?></p><?php if ($s['price_note']!==''): ?><strong><?=e($s['price_note'])?></strong><?php endif ?><?php if ((int)$s['rate_poisha_per_1000']>0): ?><p><a href="/orders/new">Order service →</a></p><?php endif ?></article><?php endforeach ?><?php if (!$services): ?><p>Our catalogue is being prepared. Please check back later.</p><?php endif ?></div></section>
<?php elseif ($path==='/login' || $path==='/register'): ?><section class="auth-wrap"><div class="auth-card"><div class="eyebrow">MEXA MOTION ACCOUNT</div><h1><?=$path==='/login'?'Welcome back.':'Make your move.'?></h1><p><?=$path==='/login'?'Sign in to your workspace.':'Create an account to get started.'?></p><form method="post" action="<?=e($path)?>"><?=csrf_field()?><?php if ($path==='/register'): ?><label>Name<input name="name" maxlength="100" required autocomplete="name"></label><?php endif ?><label>Email address<input type="email" name="email" maxlength="190" required autocomplete="email"></label><label>Password<input type="password" name="password" minlength="12" maxlength="72" required autocomplete="<?=$path==='/login'?'current-password':'new-password'?>"></label><button class="btn" type="submit"><?=$path==='/login'?'Sign in':'Create account'?> ↗</button></form><p class="auth-switch"><?=$path==='/login'?'New here?':'Already have an account?'?> <a href="<?=$path==='/login'?'/register':'/login'?>"><?=$path==='/login'?'Create an account':'Sign in'?></a></p></div></section>
